# -*- coding: utf-8 -*-
"""Science Stage 8 · Unit 2 Human Body Systems – Read the lesson (shown below the video) and the lesson document (PDF).
Camday's own text, examples and questions; scope: Cambridge Lower Secondary Science 0893, Stage 8 (8Bs.01–8Bs.04, 8Bp.04, 8Bp.05, 8TWSm.01)."""
from maths_notes_v4.kit4 import H, I, Y, X, K, L, W, BK, Ex, mcq, grid, num

READ = {}
CARD = lambda title, cards, cols=None: dict({"kind": "sciCards", "title": title, "cards": cards}, **({"cols": cols} if cols else {}))
LB = lambda base, *labels, **kw: dict({"kind": "sciLabel", "base": base, "labels": [list(l) for l in labels]}, **kw)

# =====================================================================================================
# 2.1 The musculoskeletal system · 8Bs.01, 8TWSm.01
# =====================================================================================================
READ["2.1"] = L(
    H("A body without bones",
      "Imagine you had no skeleton at all. Could you stand up? Could you walk? What would protect your brain?",
      "Write down three jobs you think the skeleton does."),
    I("The skeleton",
      "The **musculoskeletal system** is made of **bones**, **joints** and **muscles**. The bones together form the **skeleton**.",
      fig=CARD("Jobs of the skeleton", [{"t": "Support", "d": "holds the body up and gives it shape"}, {"t": "Protection", "d": "skull protects the brain; ribs protect the heart and lungs"},
                                         {"t": "Movement", "d": "muscles pull on bones at joints"}, {"t": "Making blood cells", "d": "in the marrow of some bones"}], 4),
      then=["A baby's bones are soft; they harden as a child grows. Bone is remarkably strong for its mass – much stronger than a steel bar of the same mass."]),
    I("Joints",
      "A **joint** is where two or more bones meet. Bones cannot bend, so we move at joints.",
      table=[["Type of joint", "Movement", "Examples"], ["**fixed**", "none", "between the bones of the skull and the pelvis"],
             ["**ball-and-socket**", "in many directions, even a full circle", "shoulder, hip"], ["**hinge**", "back and forth in one direction, like a door", "elbow, knee, fingers"]],
      then=["Comparing a joint to a door hinge is an **analogy**: it explains something new using something familiar. Every analogy has limits – a door hinge has no cartilage or fluid to cushion it."]),
    Y("Which joint?",
      grid("s8u02r11", "Which type of joint is it?", ["Ball-and-socket", "Hinge", "Fixed"],
           [("shoulder", "Ball-and-socket"), ("knee", "Hinge"), ("skull", "Fixed"), ("hip", "Ball-and-socket"), ("finger", "Hinge")],
           "Can it move in a circle, one direction, or not at all?", "Shoulder and hip turn in circles; knee and fingers bend one way; the skull does not move.")),
    I("Predict, watch, explain: can a muscle push?",
      "A model arm has two card 'bones' joined at the elbow and a strip of elastic as the biceps. Pushing the elastic just makes it buckle; **pulling** it lifts the lower arm.",
      then=["A muscle can only **pull**, by **contracting** (getting shorter and fatter). It cannot push. So how does the arm straighten again? A second muscle pulls the other way."]),
    I("Antagonistic muscles",
      "Skeletal muscles are attached to bones by tough cords called **tendons**. Muscles work in **antagonistic pairs**: two muscles that pull in **opposite directions**.",
      fig={"kind": "sciArm"},
      table=[["Movement", "Biceps", "Triceps"], ["bending the arm", "**contracts**", "relaxes"], ["straightening the arm", "relaxes", "**contracts**"]],
      then=["The hamstrings and quadriceps in the thigh are another antagonistic pair: they bend and straighten the knee."]),
    Y("Why pairs?",
      mcq("s8u02r12", "Why do muscles work in antagonistic pairs?",
          [("Muscles can only pull, so a second muscle is needed to move the bone back.", True, "Yes."), ("One muscle is too weak to move a bone.", False, "One muscle can move a bone, but only one way."),
           ("Muscles push and pull at the same time.", False, "Muscles never push."), ("The pairs keep the bones warm.", False, "That is not their job.")],
          "Can a muscle push?", "Each muscle can only pull, so pairs pull in opposite directions.")),
    K("Key points",
      "The skeleton supports, protects, allows movement and makes blood cells.",
      "Joints: **fixed**, **ball-and-socket** (shoulder, hip), **hinge** (elbow, knee).",
      "Muscles are joined to bones by **tendons**; they can only **pull** (contract).",
      "**Antagonistic pairs** such as biceps and triceps pull in opposite directions."),
    book=BK(
        [("skeleton", "all the bones of the body"), ("joint", "where two or more bones meet"), ("tendon", "a tough cord joining a muscle to a bone"),
         ("contract", "get shorter (a muscle pulling)"), ("antagonistic pair", "two muscles that pull in opposite directions"), ("analogy", "a comparison with something familiar")],
        [], [],
        [Ex("Give four jobs of the skeleton.", ans="support, protection, movement, making blood cells"),
         Ex("Name the type of joint and the movement it allows: (a) hip (b) elbow.", ans="(a) ball-and-socket – many directions (b) hinge – one direction, back and forth"),
         Ex("Describe what the biceps and triceps do when you lift a cup to your mouth.", ans="The biceps contracts and the triceps relaxes, so the arm bends."),
         Ex("A door hinge is used as an analogy for the knee. Give one way it is a good analogy and one limitation.", ans="Good: both move back and forth in one direction. Limit: a knee has muscles, cartilage and fluid; a hinge does not.", think=True)],
        ["describe the jobs of the skeleton", "identify ball-and-socket and hinge joints", "explain how antagonistic muscles move a joint"],
        look=["the joints table", "the biceps and triceps diagram"],
        note="Read it after the video: the skeleton, joints and antagonistic muscles (answers at the back)."),
)

# =====================================================================================================
# 2.2 The respiratory system · 8Bs.03, 8Bs.04, 8Bp.04, 8Bp.05
# =====================================================================================================
READ["2.2"] = L(
    H("Breathing or respiring?",
      "'Respiration' and 'breathing' are often used to mean the same thing. In science they are very different.",
      "Write what you think each word means, then compare at the end of the lesson."),
    I("The respiratory system",
      "Air travels into the body along this path:",
      fig={"kind": "sciFlow", "title": "The path of air", "steps": [{"t": "Nose and mouth"}, {"t": "Trachea (windpipe)"}, {"t": "Bronchi", "d": "one to each lung"},
                                                               {"t": "Bronchioles", "d": "smaller tubes"}, {"t": "Alveoli", "d": "tiny air sacs"}]},
      then=["The lungs are protected by the **ribs**. The **intercostal muscles** lie between the ribs, and the **diaphragm** – a dome-shaped sheet of muscle – lies below the lungs."]),
    I("Breathing in and out",
      "**Breathing** (ventilation) moves air into and out of the lungs.",
      fig={"kind": "lungmodel"},
      table=[["", "Breathing in (inhaling)", "Breathing out (exhaling)"],
             ["intercostal muscles", "contract: ribs move up and out", "relax: ribs move down and in"], ["diaphragm", "contracts and flattens (moves down)", "relaxes and domes upwards"],
             ["volume of chest", "increases", "decreases"], ["pressure in lungs", "falls below air pressure outside", "rises above air pressure outside"], ["air", "rushes in", "is pushed out"]],
      then=["In the bell-jar model, pulling the rubber sheet down (diaphragm) makes the balloons (lungs) inflate."]),
    I("Predict, watch, explain: what is in breathed-out air?",
      "Room air is bubbled through one tube of limewater; a student gently breathes out through a straw into another. The limewater with breathed-out air turns milky much faster.",
      fig={"kind": "barchart", "labels": ["O₂ in", "O₂ out", "CO₂ in", "CO₂ out"], "values": [21, 16, 0.04, 4], "ymax": 25, "step": 5, "ylabel": "percentage of the air (%)", "xlabel": "gas"},
      then=["Breathed-out air has **less oxygen** (16% instead of 21%) and about **100 times more carbon dioxide** (4% instead of 0.04%). It also has more water vapour – breathe on a cold mirror and it mists up.",
            "The missing oxygen went into the blood; the extra carbon dioxide came from **respiration** in our cells."]),
    I("Gas exchange in the alveoli",
      "Each **alveolus** is wrapped in a network of tiny blood vessels called **capillaries**.",
      then=["Oxygen moves from the air in the alveoli into the blood; carbon dioxide moves from the blood into the alveoli to be breathed out.",
            "The gases move by **diffusion** – from where there is a **high concentration** to where there is a **low concentration**.",
            "Alveoli are good at gas exchange: there are millions of them (a huge surface area), their walls are **one cell thick**, they are moist, and they have a rich blood supply."]),
    I("Aerobic respiration",
      "**Respiration** is a chemical process in every living cell that **releases energy from food**. Aerobic respiration uses oxygen and happens in the **mitochondria**:",
      table=[["Reactants", "", "Products"], ["**glucose + oxygen**", "→", "**carbon dioxide + water**"]],
      then=["The energy released powers all life processes, all the time – even when you are asleep. Plants and germinating seeds respire too.",
            "**Breathing** is a physical process that moves air; **respiration** is a chemical reaction in cells."]),
    Y("Breathing or respiration?",
      grid("s8u02r21", "Is each statement about breathing or respiration?", ["Breathing", "Respiration"],
           [("happens in the mitochondria", "Respiration"), ("the diaphragm moves down", "Breathing"), ("releases energy from glucose", "Respiration"), ("air moves into the lungs", "Breathing"),
            ("happens in plant cells too", "Respiration")],
           "Physical movement of air, or a chemical reaction in cells?", "Mitochondria, glucose and plants → respiration; diaphragm and air movement → breathing.")),
    K("Key points",
      "Air path: nose → trachea → bronchi → bronchioles → alveoli.",
      "Breathing in: intercostals and diaphragm contract, chest volume up, pressure down, air in. Breathing out: the reverse.",
      "Breathed-out air: less oxygen, more carbon dioxide and water vapour.",
      "Gas exchange in alveoli by **diffusion**; thin walls, large surface area, good blood supply.",
      "**Aerobic respiration**: glucose + oxygen → carbon dioxide + water (+ energy), in mitochondria."),
    book=BK(
        [("trachea", "the windpipe"), ("alveoli", "tiny air sacs in the lungs where gas exchange happens"), ("diaphragm", "a sheet of muscle below the lungs"),
         ("diffusion", "movement of particles from a high to a low concentration"), ("aerobic respiration", "releasing energy from glucose using oxygen")],
        [], [],
        [Ex("Put in order: alveoli, trachea, bronchiole, nose, bronchus.", ans="nose, trachea, bronchus, bronchiole, alveoli"),
         Ex("Describe what the diaphragm and intercostal muscles do when you breathe in.", ans="Both contract: ribs move up and out, diaphragm flattens; chest volume increases, pressure falls, air rushes in."),
         Ex("Give three differences between inhaled and exhaled air.", ans="exhaled air has less oxygen, more carbon dioxide, more water vapour (and is warmer)"),
         Ex("Write the word equation for aerobic respiration.", ans="glucose + oxygen → carbon dioxide + water"),
         Ex("Explain how the structure of alveoli helps gas exchange.", ans="Huge surface area, walls one cell thick so gases diffuse quickly, moist surface, rich supply of capillaries.", think=True)],
        ["describe the respiratory system", "explain breathing in and out", "explain gas exchange by diffusion", "tell breathing from respiration and write the word equation"],
        look=["the breathing table", "inhaled and exhaled air"],
        note="Read it after the video: the respiratory system, breathing, gas exchange and aerobic respiration (answers at the back)."),
)

# =====================================================================================================
# 2.3 The circulatory system · 8Bs.02
# =====================================================================================================
READ["2.3"] = L(
    H("A city's delivery service",
      "A big city needs roads, delivery vans and a central depot to move food to every home and take rubbish away.",
      "Your body has a delivery service too. What do you think plays the part of the roads, the vans and the depot?"),
    I("Heart, blood vessels and blood",
      "The **circulatory system** is the body's transport system. It has three parts: the **heart** (pump), **blood vessels** (roads) and **blood** (what is carried).",
      then=["The heart is a **double pump**: the **right side** pumps deoxygenated blood to the **lungs**; the **left side** pumps oxygenated blood to the **rest of the body**."]),
    I("Blood vessels",
      "Three kinds of blood vessel:",
      table=[["Vessel", "Carries blood …", "Features"],
             ["**arteries**", "**away** from the heart (usually oxygenated)", "thick, muscular, elastic walls – blood under high pressure"],
             ["**veins**", "**back** to the heart (usually deoxygenated)", "thinner walls, valves stop blood flowing backwards"],
             ["**capillaries**", "between arteries and veins, through every tissue", "walls one cell thick – oxygen and nutrients pass into cells, carbon dioxide and waste pass out"]]),
    Y("Which vessel?",
      grid("s8u02r31", "Which blood vessel is described?", ["Artery", "Vein", "Capillary"],
           [("carries blood away from the heart", "Artery"), ("has valves", "Vein"), ("wall only one cell thick", "Capillary"), ("blood under the highest pressure", "Artery")],
           "Away, back, or between?", "Away and high pressure → artery; valves → vein; one cell thick → capillary.")),
    I("What is blood made of?",
      "Spin blood fast in a centrifuge and it separates into layers. An adult has about 5 litres of blood.",
      fig={"kind": "pie", "labels": ["plasma 55%", "red blood cells 44%", "white cells and platelets 1%"], "values": [55, 44, 1]},
      table=[["Part", "Job"],
             ["**plasma**", "yellow liquid that carries blood cells, dissolved glucose, nutrients, hormones and carbon dioxide"],
             ["**red blood cells**", "carry **oxygen** – full of **haemoglobin**, no nucleus, biconcave disc shape for a large surface area"],
             ["**white blood cells**", "defend the body: some engulf pathogens (**phagocytosis**), others make **antibodies**"],
             ["**platelets**", "fragments of cells that help blood **clot** and form scabs"]]),
    Y("Which part of the blood?",
      mcq("s8u02r32", "Which part of the blood carries dissolved glucose and carbon dioxide?",
          [("plasma", True, "Yes – they dissolve in the plasma."), ("red blood cells", False, "They carry oxygen."), ("white blood cells", False, "They fight infection."),
           ("platelets", False, "They help clotting.")],
          "Which part is a liquid?", "Plasma carries dissolved substances.")),
    I("Blood groups and donation",
      "People have different **blood groups**: A, B, AB and O, each Rh positive or negative.",
      then=["Blood given in a **transfusion** must match, or the patient's antibodies attack it. **O negative** people are universal **donors**; **AB positive** people are universal **recipients**.",
            "Donating blood is safe for healthy adults and saves lives after accidents, operations and childbirth."]),
    K("Key points",
      "The circulatory system: heart (double pump), blood vessels, blood.",
      "**Arteries** away from the heart (thick walls); **veins** back to the heart (valves); **capillaries** exchange substances with cells.",
      "Blood: **plasma** (transport), **red cells** (oxygen, haemoglobin), **white cells** (defence), **platelets** (clotting).",
      "Blood groups A, B, AB, O; O negative is the universal donor."),
    book=BK(
        [("artery", "a blood vessel carrying blood away from the heart"), ("vein", "a blood vessel carrying blood back to the heart"),
         ("capillary", "a tiny blood vessel with walls one cell thick"), ("plasma", "the liquid part of blood"), ("haemoglobin", "red substance that carries oxygen"),
         ("platelet", "a cell fragment that helps blood clot"), ("antibody", "a substance made by white blood cells that disables pathogens")],
        [], [],
        [Ex("Explain why the heart is called a double pump.", ans="The right side pumps blood to the lungs and the left side pumps blood to the rest of the body."),
         Ex("Give one way each blood vessel suits its job: (a) artery (b) vein (c) capillary.", ans="(a) thick elastic wall for high pressure (b) valves stop backflow (c) one-cell-thick wall for exchange"),
         Ex("Name the part of the blood that: (a) carries oxygen (b) helps clotting (c) makes antibodies.", ans="(a) red blood cells (b) platelets (c) white blood cells"),
         Ex("Quick quiz.", ("What type of joint is the elbow?", "a hinge joint"), ("Why do muscles work in pairs?", "they can only pull"),
            ("Word equation for aerobic respiration?", "glucose + oxygen → carbon dioxide + water"), ("Which vessels carry blood away from the heart?", "arteries")),
         Ex("Explain how the shape and contents of a red blood cell help it carry oxygen.", ans="No nucleus leaves more room for haemoglobin; the biconcave disc gives a large surface area for oxygen to diffuse in and out.", think=True)],
        ["describe the heart and blood vessels", "describe the parts of blood and their jobs", "explain blood groups and donation"],
        look=["the blood vessel table", "the parts of blood"],
        note="Read it after the video: the heart, blood vessels, blood and blood groups, plus a quick quiz (answers at the back)."),
)
